<?php
declare(strict_types=1); require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/includes/auth.php';$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$status=$_POST['status']??'read';$allowed=['new','read','replied','archived'];if($id&&in_array($status,$allowed,true)){db()->prepare('UPDATE messages SET status=? WHERE id=?')->execute([$status,$id]);}header('Location: messages.php');exit;}$rows=db()->query('SELECT * FROM messages ORDER BY created_at DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="dashboard.php">Distinguished Web Services</a><a class="btn btn-outline-light btn-sm" href="logout.php">Logout</a></div></nav><main class="container py-5"><h1 class="h2 mb-4">Project Enquiries</h1><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Contact</th><th>Service</th><th>Budget</th><th>Message</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=$esc($r['name']??'')?></strong><div><?=$esc($r['email']??'')?></div><small class="text-muted"><?=$esc($r['phone']??'')?></small></td><td><?=$esc($r['service']??'')?></td><td><?=$esc($r['budget']??'')?></td><td style="max-width:320px"><?=nl2br($esc($r['message']??''))?></td><td><form method="post"><input type="hidden" name="id" value="<?=((int)($r['id']??0))?>"><select name="status" class="form-select form-select-sm" onchange="this.form.submit()"><option value="new" <?=((string)($r['status']??'')==='new'?'selected':'')?>>New</option><option value="read" <?=((string)($r['status']??'')==='read'?'selected':'')?>>Read</option><option value="replied" <?=((string)($r['status']??'')==='replied'?'selected':'')?>>Replied</option><option value="archived" <?=((string)($r['status']??'')==='archived'?'selected':'')?>>Archived</option></select></form></td><td><?=$esc($r['created_at']??'')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center py-5 text-muted">No enquiries yet.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>